updated_projects as (
  update public.projects p
  set
    problem_solved = d.problem_solved,
    how_it_works = p.short_description ||
      ' The app then presents the result in a clear view so the user can review the next step.',
    real_world_application = c.description || ' ' || c.build_examples,
    main_features = array[
      p.short_description,
      'A clear result or status view',
      'A way to review or update information'
    ]::text[],
    learning_outcomes = array[
      'Plan the main steps for ' || lower(p.title),
      'Use ' || array_to_string(p.technologies, ', ') || ' in a complete workflow',
      'Check the result with sample data'
    ]::text[]
  from project_problems d, public.project_categories c
  where p.slug = d.slug
    and c.id = p.category_id
  returning p.slug
)
select count(*) as corrected_project_count from updated_projects;
